  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 Computers, Hardware and Software$j$, $j${"readings": [{"title": "Exodus 31 (King James Version)", "url": "/portal/bible/Exodus/31"}], "body": "A computer is an electronic machine that accepts input, processes it, stores it and produces output. Every device you use follows this cycle. When you type a key, that is input. The processor works on it. The screen showing the letter is output. Saved files are storage.\n\nHardware is the physical part of a computer that you can touch. The central processing unit, or CPU, is the brain that carries out instructions. Random access memory, or RAM, is short term working memory that is cleared when the power goes off. Storage, such as a solid state drive, keeps files even when the power is off. The motherboard connects the parts. Input devices include a keyboard, mouse, microphone and camera. Output devices include a monitor, printer and speakers. Phones, tablets and laptops are computers too.\n\nSoftware is the set of instructions that tells hardware what to do. System software, such as an operating system, manages the machine. Application software, such as a word processor, a browser or a game, helps you do tasks.\n\nComputers store everything as bits. A bit is a single zero or one. Eight bits make a byte, and bytes are counted in kilobytes, megabytes, gigabytes and terabytes. Binary code is the zeros and ones that machines understand.\n\nGod gives people skill to build useful things. Exodus 31:3 says of Bezaleel, And I have filled him with the spirit of God, in wisdom, and in understanding, and in knowledge, and in all manner of workmanship. Technology is a tool, and a believer can learn it with excellence and use it to serve God and others. Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men.\n\nYour task: (1) Name the four parts of the computing cycle. (2) Explain the difference between RAM and storage. (3) Explain the difference between hardware and software.\n\nFlorida standards: SC.912.CS.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.CS", "script": "Welcome back. Listen, Exodus 31:3 says God filled Bezaleel with wisdom, and understanding, and knowledge, and in all manner of workmanship. God gives people skill to build useful things, and technology is one of them.\n\nNow watch this. A computer accepts input, processes it, stores it and produces output. Type a key, that is input. The CPU, the brain, processes it. The screen shows the output. Saved files are storage.\n\nHardware is the part you can touch. The CPU thinks. RAM is short term working memory that clears when the power goes off. Storage keeps files when the power is off. Keyboards, mice and microphones are input devices. Monitors, printers and speakers are output devices.\n\nSoftware is the instructions. System software like an operating system manages the machine. Application software like a word processor or browser helps you do tasks.\n\nEverything is stored as bits, zeros and ones. Eight bits make a byte.\n\nYour task is to name the computing cycle, compare RAM and storage and compare hardware and software. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 Computers, Hardware and Software$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 Operating Systems, Files and Folders$j$, $j${"readings": [{"title": "1 Corinthians 14 (King James Version)", "url": "/portal/bible/1Corinthians/14"}], "body": "An operating system, or OS, is the main software that manages a computer. It controls the hardware, runs applications, provides the screen you see and organizes files. Common operating systems include Windows, macOS, ChromeOS and Linux for computers, and Android and iOS for phones and tablets. An application must be made to work with the operating system it runs on.\n\nA file is a named collection of information. A folder, also called a directory, holds files and other folders. Good organization saves time. 1 Corinthians 14:40 says, Let all things be done decently and in order. Use clear names such as Science Report Draft 2 instead of New Document. Group files in folders by subject or project. Avoid spaces and symbols that cause trouble when files are shared, and never rely on a vague name like final final.\n\nThe end of a file name, called the file extension, tells the computer what kind of file it is. A docx file is a word processing document, an xlsx file is a spreadsheet, a pptx file is a presentation, a pdf file is a fixed layout document, a jpg or png file is an image, an mp3 file is audio and an mp4 file is video. Knowing the format helps you choose the right program and share files correctly.\n\nLearn basic file skills: create, name, open, save, copy, move, rename, delete and search. Know the difference between Save and Save As. Use the recycle bin or trash carefully, since deleted files may not return.\n\nProtect your work with backups. A common rule is to keep three copies of important files, on two kinds of storage, with one copy in a different place such as cloud storage. Hard drives fail, phones are lost and files are deleted by mistake, so back up often.\n\nYour task: (1) Name four jobs of an operating system. (2) Match five file extensions with their file types. (3) Describe your backup plan.\n\nFlorida standards: SC.912.CS.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.CS", "script": "Welcome back. Listen, 1 Corinthians 14:40 says, Let all things be done decently and in order. That applies to our files too.\n\nNow watch this. The operating system is the main software that manages the computer. It controls hardware, runs applications, gives you the screen and organizes files. Windows, macOS, ChromeOS and Linux run on computers. Android and iOS run on phones and tablets.\n\nA file is a named collection of information. A folder holds files. Use clear names, like Science Report Draft 2, not New Document. Group files by subject or project.\n\nThe file extension tells the computer the type. Docx is a word document. Xlsx is a spreadsheet. Pptx is a presentation. Pdf is a fixed layout document. Jpg and png are images. Mp3 is audio. Mp4 is video.\n\nLearn to create, name, save, copy, move, rename, delete and search. Know Save and Save As.\n\nBack up your work. Keep three copies, on two kinds of storage, with one in a different place like the cloud.\n\nYour task is to name the jobs of an operating system, match extensions and describe your backup plan. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 Operating Systems, Files and Folders$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Digital Citizenship, Ethics and Stewardship of Technology$j$, $j${"readings": [{"title": "Philippians 4 (King James Version)", "url": "/portal/bible/Philippians/4"}], "body": "A digital citizen uses technology responsibly, respectfully and safely. The Lord is as concerned with how we behave online as how we behave in person. Matthew 7:12 says, Therefore all things whatsoever ye would that men should do to you, do ye even so to them: for this is the law and the prophets. Ephesians 4:29 says, Let no corrupt communication proceed out of your mouth, but that which is good to the use of edifying, that it may minister grace unto the hearers.\n\nYour digital footprint is the record of everything you post, share, search and click. It can last for years, be copied and be seen by schools, employers and others. Before posting, ask whether it is true, kind and necessary, and whether you would be comfortable if a parent or pastor saw it. Netiquette means good manners online: avoid all capital letters that look like shouting, think before replying, and do not forward rumors.\n\nCyberbullying is the use of technology to harass, embarrass or threaten others. It is wrong. If you are targeted, save the evidence, do not respond in anger, block the person, and tell a trusted adult. If you see it happening, do not join in, and support the person who is hurt.\n\nRespect creators. Plagiarism is presenting another person's words or ideas as your own. Copyright law protects original works from the moment they are created. Fair use allows limited use of copyrighted material for purposes such as education or commentary, but it is a defense judged case by case and not a free pass to copy. To use materials legally, look for permission, public domain works or Creative Commons licenses, and always give credit. Downloading pirated music, movies or software is stealing.\n\nTechnology also calls for balance. Time is a gift, and a faithful steward should manage screen time, sleep, study, family, church and service. Philippians 4:8 teaches us what to dwell on: whatsoever things are true, whatsoever things are honest, whatsoever things are just, whatsoever things are pure, whatsoever things are lovely.\n\nYour task: (1) Define digital footprint. (2) List three steps to take if you are cyberbullied. (3) Explain the difference between plagiarism and giving credit.\n\nFlorida standards: SC.912.CS.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.CS", "script": "Welcome back. Listen, Matthew 7:12 says, all things whatsoever ye would that men should do to you, do ye even so to them. And Ephesians 4:29 says, Let no corrupt communication proceed out of your mouth, but that which is good to the use of edifying. That is how we behave online.\n\nNow watch this. Your digital footprint is the record of what you post, share, search and click. It can last for years. Before you post, ask if it is true, kind and necessary.\n\nNetiquette is good manners online. Think before replying and do not forward rumors.\n\nCyberbullying is wrong. If you are targeted, save the evidence, do not answer in anger, block the person and tell a trusted adult. If you see it, do not join in.\n\nRespect creators. Plagiarism is presenting someone else's work as your own. Copyright protects original works from the moment they are created. Fair use is limited and judged case by case. Look for permission, public domain or Creative Commons, and give credit. Pirated downloads are stealing.\n\nManage your time. Philippians 4:8 says think on whatsoever things are true, honest, just, pure and lovely.\n\nYour task is to define digital footprint, list steps for cyberbullying and explain plagiarism. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Digital Citizenship, Ethics and Stewardship of Technology$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 Online Safety, Passwords and Privacy$j$, $j${"readings": [{"title": "Proverbs 4 (King James Version)", "url": "/portal/bible/Proverbs/4"}], "body": "The internet is a useful place and also a place with dangers. Proverbs 22:3 says, A prudent man foreseeth the evil, and hideth himself: but the simple pass on, and are punished. Proverbs 4:23 says, Keep thy heart with all diligence; for out of it are the issues of life. Online safety protects your heart, your mind, your information and your family.\n\nProtect personal information such as your full name, address, school, phone number, passwords, birth date and financial details. Never post them publicly, and be careful about what you share even with friends. Turn off location sharing for photos and posts unless you need it. Remember that people online may not be who they say they are. Never meet someone you only know online, and tell a parent or trusted adult if a stranger contacts you or asks for photos or secrets.\n\nPasswords are the keys to your accounts. A strong password is long, at least twelve to sixteen characters, and unique for each account. A passphrase made of several unrelated words is easy to remember and hard to guess. Do not use names, birthdays or common words such as password. Never reuse a password, never share it, and never write it where others can see it. A password manager can create and store strong passwords safely.\n\nTurn on multifactor authentication where it is offered. After your password, the account asks for a second proof, such as a code sent to your phone or an app. This stops most attackers even when a password is stolen.\n\nReview privacy settings on apps and social media, and limit who can see your posts. Read what permissions an app asks for, and do not install apps that ask for more than they need. Log out of shared computers. Keep software updated, since updates fix security problems. Be careful on public WiFi, and avoid banking or entering passwords on it.\n\nSinful content and unsafe sites are traps. Psalm 101:3 says, I will set no wicked thing before mine eyes. Use filters, ask for accountability and turn away from what harms you.\n\nYour task: (1) List five kinds of personal information to protect. (2) Create an example of a strong passphrase that is not your real password. (3) Explain multifactor authentication.\n\nFlorida standards: SC.912.CS.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.CS", "script": "Welcome back. Listen, Proverbs 22:3 says, A prudent man foreseeth the evil, and hideth himself. And Proverbs 4:23 says, Keep thy heart with all diligence; for out of it are the issues of life. Online safety protects your heart, your mind and your family.\n\nNow watch this. Protect personal information: your full name, address, school, phone number, passwords and birth date. Turn off location sharing unless you need it. People online may not be who they say they are. Never meet someone you only know online, and tell a trusted adult if a stranger contacts you.\n\nA strong password is long, at least twelve to sixteen characters, and unique. A passphrase of several unrelated words is easy to remember and hard to guess. Never reuse or share it. A password manager can help.\n\nTurn on multifactor authentication. After the password, the account asks for a second proof, like a code sent to your phone.\n\nReview privacy settings. Keep software updated. Be careful on public WiFi.\n\nPsalm 101:3 says, I will set no wicked thing before mine eyes. Use filters and accountability.\n\nYour task is to list personal information, create a sample passphrase and explain multifactor authentication. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 Online Safety, Passwords and Privacy$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Computing Foundations and Digital Citizenship$j$, $j${"prompt": "Write a report of at least 250 words on computers and responsible technology use. Use complete sentences and label each part. Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men.\n\nPart 1: Explain the computing cycle of input, processing, storage and output. Give an example of each. Define hardware and software, and explain the difference between RAM and storage.\nPart 2: Name four jobs of an operating system and three examples of operating systems. Match five file extensions with their file types, and describe a folder system you would use for school work.\nPart 3: Describe your backup plan using the rule of three copies, two kinds of storage and one different location.\nPart 4: Define digital footprint, plagiarism and copyright. Explain the steps you would take if you were bullied online.\nPart 5: Describe how to protect personal information, create strong passwords and use multifactor authentication. Explain how Matthew 7:12, Proverbs 22:3 and Philippians 4:8 guide a believer online.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 10 points. Part 4: 20 points. Part 5: 25 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Computing Foundations and Digital Citizenship$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Whatsoever Ye Would That Men Should Do to You$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a time when technology helped you or someone you know, with no names, (2) explains in your own words what it means to be a good digital citizen, (3) explains one habit you will practice to stay safe and kind online, and (4) connects your answer to Matthew 7:12, Ephesians 4:29, Proverbs 22:3 or Philippians 4:8. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can a Christian use social media to encourage others? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Whatsoever Ye Would That Men Should Do to You$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: Computers, Hardware and Software$j$, $j${"questions": [{"q": "The physical parts of a computer that you can touch are called:", "options": ["Software", "Hardware", "Output", "Binary"]}, {"q": "Short term working memory that clears when power is off is:", "options": ["A monitor", "A solid state drive", "RAM", "A keyboard"]}, {"q": "Eight bits make one:", "options": ["Byte", "Gigabyte", "Kilobyte", "Pixel"]}, {"q": "A keyboard is an example of:", "options": ["A network", "An input device", "An output device", "System software"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Computers, Hardware and Software$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,0,1}'::int[], array[$j$Hardware is the physical equipment.$j$,$j$RAM is temporary working memory.$j$,$j$A byte is eight bits.$j$,$j$A keyboard sends information into the computer.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Computers, Hardware and Software$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Operating Systems, Files and Folders$j$, $j${"questions": [{"q": "The main software that manages a computer is the:", "options": ["Operating system", "Browser", "Printer", "Monitor"]}, {"q": "A pptx file is a:", "options": ["Audio file", "Image", "Spreadsheet", "Presentation"]}, {"q": "Which is an operating system for phones?", "options": ["Android", "Excel", "Keyboard", "Chrome extension"]}, {"q": "A good backup plan keeps copies:", "options": ["In more than one place", "Only in the recycle bin", "Only on the desktop", "Nowhere"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Operating Systems, Files and Folders$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,0,0}'::int[], array[$j$The OS controls hardware and software.$j$,$j$Pptx files are presentations.$j$,$j$Android and iOS run on phones.$j$,$j$Separate copies protect against loss.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Operating Systems, Files and Folders$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Digital Citizenship, Ethics and Stewardship of Technology$j$, $j${"questions": [{"q": "The record of everything you post, share and click online is your:", "options": ["Backup", "Digital footprint", "Operating system", "Firewall"]}, {"q": "Presenting someone else's work as your own is:", "options": ["Backup", "Fair use", "Plagiarism", "Netiquette"]}, {"q": "If you are cyberbullied, a wise first step is to:", "options": ["Join in", "Save the evidence and tell a trusted adult", "Reply in anger", "Delete everything and say nothing"]}, {"q": "Copyright protection begins:", "options": ["Only after a fee is paid", "After 50 years", "Never", "When a work is created"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Digital Citizenship, Ethics and Stewardship of Technology$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,1,3}'::int[], array[$j$Your digital footprint can last for years.$j$,$j$Plagiarism is dishonest.$j$,$j$Evidence and adult help are important.$j$,$j$Original works are protected from creation.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Digital Citizenship, Ethics and Stewardship of Technology$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: Online Safety, Passwords and Privacy$j$, $j${"questions": [{"q": "A strong password is generally:", "options": ["The word password", "Short and easy", "Your birthday", "Long and unique"]}, {"q": "Multifactor authentication adds:", "options": ["A second proof of identity", "More storage", "A louder alarm", "A faster screen"]}, {"q": "Which should you NOT post publicly?", "options": ["A sermon quote", "Your home address and passwords", "A school achievement without private details", "A Bible verse you like"]}, {"q": "If a stranger online asks you for photos or secrets, you should:", "options": ["Keep it a secret", "Meet them", "Send them", "Tell a parent or trusted adult"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Online Safety, Passwords and Privacy$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,1,3}'::int[], array[$j$Length and uniqueness protect accounts.$j$,$j$It asks for another proof after the password.$j$,$j$Private details can be misused.$j$,$j$A trusted adult can help protect you.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Online Safety, Passwords and Privacy$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Computing Foundations and Digital Citizenship$j$, $j${"questions": [{"q": "The CPU is best described as the:", "options": ["Printer", "Cloud", "Brain that carries out instructions", "Password"]}, {"q": "Software that manages the computer and its files is the:", "options": ["Operating system", "Monitor", "Speaker", "Keyboard"]}, {"q": "A pdf file is best described as a:", "options": ["Spreadsheet", "Fixed layout document", "Audio file", "Video"]}, {"q": "Which is an output device?", "options": ["Printer", "Microphone", "Keyboard", "Mouse"]}, {"q": "Ephesians 4:29 teaches that our words should be:", "options": ["Angry", "Good to the use of edifying", "Sarcastic", "Secret"]}, {"q": "The best response to a phishing style message from a stranger is to:", "options": ["Ignore it and tell a trusted adult", "Click the link", "Reply with your password", "Forward it to friends"]}, {"q": "A passphrase is:", "options": ["Several unrelated words used as a long password", "A short number", "Your name", "A shared code"]}, {"q": "Proverbs 22:3 says a prudent man:", "options": ["Passeth on", "Never works", "Foreseeth the evil, and hideth himself", "Believeth every word"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Computing Foundations and Digital Citizenship$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,1,0,1,0,0,2}'::int[], array[$j$The CPU processes instructions.$j$,$j$The OS manages the machine.$j$,$j$A pdf keeps its layout.$j$,$j$A printer produces output.$j$,$j$Our words should build up.$j$,$j$Do not engage with suspicious messages.$j$,$j$Long passphrases are strong and memorable.$j$,$j$Prudence means preparing for danger.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Computing Foundations and Digital Citizenship$j$ on conflict (item_id) do nothing;
